// Mesa Estelar v145 — Arte da Casa Vaelkor (retrato de Lord Anthorion Vaelkor, moedas e cédulas do Domínio Vaelkor).
// Imagens pequenas (WebP) embutidas no código para não pesar o banco de dados nem depender de upload.
export const ARTE_VAELKOR=Object.freeze({
 ouro:'data:image/webp;base64,',
 prata:'data:image/webp;base64,',
 cobre:'data:image/webp;base64,',
 bimetal:'data:image/webp;base64,',
 reverso50:'data:image/webp;base64,',
 nota1000:'data:image/webp;base64,',
 nota500:'data:image/webp;base64,',
 retrato:'data:image/webp;base64,',
 busto:'data:image/webp;base64,'
});
// Valores das moedas e cédulas, do maior para o menor (créditos Vaelkor = os "recursos" da ficha).
export const DENOMINACOES=Object.freeze([
 {id:'nota1000',valor:1000,nome:'Nota de 1000 créditos',tipo:'nota'},
 {id:'nota500',valor:500,nome:'Nota de 500 créditos',tipo:'nota'},
 {id:'ouro',valor:100,nome:'Ouro Vaelkor (100)',tipo:'moeda'},
 {id:'reverso50',valor:50,nome:'Moeda de 50',tipo:'moeda'},
 {id:'bimetal',valor:20,nome:'Bimetálica Vaelkor (20)',tipo:'moeda'},
 {id:'prata',valor:10,nome:'Prata Vaelkor (10)',tipo:'moeda'},
 {id:'cobre',valor:1,nome:'Cobre Vaelkor (1)',tipo:'moeda'}
]);
// Troca um valor em cédulas e moedas (o menor número de peças).
export function trocar(valor){let v=Math.max(0,Math.floor(Number(valor)||0));const r=[];for(const d of DENOMINACOES){const n=Math.floor(v/d.valor);if(n>0){r.push({...d,n});v-=n*d.valor;}}return r;}
